insert into public.brotherhoods ("entity_id","official_name","popular_name","foundation_text","municipality_id","canonical_see_place_id","website_url","brotherhood_types","current_procession_day","notes","history_text") values
('c0160034-0301-4000-8000-000000000001','Hermandad del Dulce Nombre de Jesús, Triunfal Entrada de Jesús en Jerusalén y Nuestra Señora de los Desamparados','Dulce Nombre y Borriquita','1582','d10878e4-8e9a-4fc5-937b-41d0282a9a0e','c0160034-0201-4000-8000-000000000001',null,array['Penitencia']::text[],'Domingo de Ramos','Registro municipal HC-016; sin escudo ni fotografía incorporados.','Fundada documentalmente el 7 de marzo de 1582; evolucionó de hermandad de gloria a corporación penitencial.'),
('c0160034-0302-4000-8000-000000000002','Real y Carmelita Hermandad y Cofradía de Nazarenos de Nuestro Padre Jesús de la Humildad y Paciencia, Cristo Atado a la Columna y María Santísima de la Soledad','Humildad y Paciencia','1602','d10878e4-8e9a-4fc5-937b-41d0282a9a0e','c0160034-0203-4000-8000-000000000003',null,array['Penitencia']::text[],'Lunes y Jueves Santo','Registro municipal HC-016; sin escudo ni fotografía incorporados.','La tradición sitúa su fundación en 1602 por el gremio de los esparteros; conserva el Vía Crucis del Lunes Santo y la estación del Jueves Santo.'),
('c0160034-0303-4000-8000-000000000003','Antigua y Humilde Hermandad del Santo Cristo de la Vera-Cruz, Jesús Cautivo y Nuestra Señora de la Esperanza','Vera-Cruz','1545','d10878e4-8e9a-4fc5-937b-41d0282a9a0e','c0160034-0204-4000-8000-000000000004',null,array['Penitencia']::text[],'Martes Santo','Registro municipal HC-016; sin escudo ni fotografía incorporados.','Fundada en 1545 en el convento franciscano de Madre de Dios; trasladada a San Agustín tras el hundimiento del templo en 1944.'),
('c0160034-0304-4000-8000-000000000004','Hermandad de Nuestra Señora del Rosario y Fátima y Cofradía de Nuestro Padre Jesús de la Salud y María Santísima de la Encarnación','Fátima',null,'d10878e4-8e9a-4fc5-937b-41d0282a9a0e','c0160034-0205-4000-8000-000000000005',null,array['Penitencia']::text[],'Miércoles Santo','Registro municipal HC-016; sin escudo ni fotografía incorporados.','Corporación del barrio de Fátima; realizó su primera salida con el Señor de la Salud en 2024.'),
('c0160034-0305-4000-8000-000000000005','Cofradía del Santísimo Cristo de la Misericordia, Nuestra Señora de la Piedad y San Juan Evangelista','Misericordia','1928','d10878e4-8e9a-4fc5-937b-41d0282a9a0e','c0160034-0206-4000-8000-000000000006',null,array['Penitencia']::text[],'Madrugá del Jueves Santo','Registro municipal HC-016; sin escudo ni fotografía incorporados.','La cofradía se organizó en 1928 y aprobó sus primeras reglas en 1929; su titular cristífero es obra de Juan de Mesa de 1623.'),
('c0160034-0306-4000-8000-000000000006','Real Hermandad de Penitencia y Humilde Esclavitud Mercedaria de Nuestro Padre Jesús Caído, Archicofradía de las Ánimas Benditas del Purgatorio, María Santísima del Rosario, Cofradía de Nazarenos de las Negaciones y Lágrimas del Señor San Pedro y Nuestra Señora y Madre de los Dolores','Jesús Caído','1705','d10878e4-8e9a-4fc5-937b-41d0282a9a0e','c0160034-0201-4000-8000-000000000001','https://www.jesuscaidoosuna.com/',array['Penitencia']::text[],'Jueves Santo','Registro municipal HC-016; sin escudo ni fotografía incorporados.','Fundada en 1705 en la iglesia de la Merced; establecida en Santo Domingo desde 1964.'),
('c0160034-0307-4000-8000-000000000007','Hermandad de Nuestro Padre Jesús Nazareno','Jesús Nazareno','1576','d10878e4-8e9a-4fc5-937b-41d0282a9a0e','c0160034-0207-4000-8000-000000000007',null,array['Penitencia']::text[],'Madrugá del Viernes Santo','Registro municipal HC-016; sin escudo ni fotografía incorporados.','Fundada el 8 de julio de 1576 y radicada históricamente en la Victoria.'),
('c0160034-0308-4000-8000-000000000008','Hermandad Sacramental y Venerable Orden Tercera de Siervos de Nuestra Madre y Señora de los Dolores','Servitas','1730','d10878e4-8e9a-4fc5-937b-41d0282a9a0e','c0160034-0207-4000-8000-000000000007',null,array['Penitencia']::text[],'Madrugá del Viernes Santo','Registro municipal HC-016; sin escudo ni fotografía incorporados.','La Orden Servita fue erigida en 1719 y la esclavitud se fundó en la Victoria en 1730.'),
('c0160034-0309-4000-8000-000000000009','Antigua, Venerable y Fervorosa Hermandad y Cofradía de Nazarenos de Nuestra Señora y Madre de la Quinta Angustia','Quinta Angustia','1580','d10878e4-8e9a-4fc5-937b-41d0282a9a0e','c0160034-0207-4000-8000-000000000007',null,array['Penitencia']::text[],'Viernes Santo','Registro municipal HC-016; sin escudo ni fotografía incorporados.','Fundada en el Convento del Espíritu Santo el 30 de octubre de 1580; actualmente radica en la Victoria.'),
('c0160034-0310-4000-8000-000000000010','Hermandad del Santo Cristo de la Paz y María Santísima del Mayor Dolor','Pax','1653','d10878e4-8e9a-4fc5-937b-41d0282a9a0e','637f8d5a-8b60-48cb-b78a-ca7f547d9d64',null,array['Penitencia']::text[],'Viernes Santo','Registro municipal HC-016; sin escudo ni fotografía incorporados.','Fundada el 4 de abril de 1653 y vinculada a la parroquia de Nuestra Señora de Consolación.'),
('c0160034-0311-4000-8000-000000000011','Hermandad del Santo Entierro de Nuestro Señor Jesucristo en el Misterio de su Muerte y Resurrección, María Santísima en su Soledad y Amargura, Triunfo de la Santa Cruz y Nuestra Señora de la Cabeza','Santo Entierro',null,'d10878e4-8e9a-4fc5-937b-41d0282a9a0e','c0160034-0208-4000-8000-000000000008',null,array['Penitencia']::text[],'Sábado Santo','Registro municipal HC-016; sin escudo ni fotografía incorporados.','Corporación histórica revitalizada desde 1993; primera estación de la etapa actual en 2000. Tiene sede en San Carlos el Real y sale desde Santa Clara.')
